from collections import Counter

def transform(grid):
    """Transform: smallest color value -> 0, largest color value -> smallest color value"""
    colors = set()
    for row in grid:
        for cell in row:
            colors.add(cell)

    if len(colors) <= 1:
        return grid

    smallest = min(colors)
    largest = max(colors)

    result = []
    for row in grid:
        new_row = []
        for cell in row:
            if cell == smallest:
                new_row.append(0)
            else:
                new_row.append(smallest)
        result.append(new_row)
    return result

